    }
}

// --- Deployment Operations --------------------------------------------------

fn create_deployment(engine: DeploymentEngine, spec: DeploymentSpec) -> DeploymentEngine {
    let state = DeploymentState {
        spec: spec,
        status: "pending",
        ready_replicas: 0,
        updated_replicas: 0,
        available_replicas: 0,
        current_revision: 1,
        deploy_start_time: timestamp_now(),
        deploy_end_time: 0,
        deploy_duration_ms: 0.0,
        conditions: []
    }

    push(engine.cluster.deployments, state)
    engine.total_deployments = engine.total_deployments + 1

    // Create initial pods
    let i = 0
    while i < spec.pod_spec.replicas {
        let pod = PodState {
            name: spec.name + "-pod-" + to_string(i),
            deployment: spec.name,
            status: "pending",
            ready: false,
            restart_count: 0,
            cpu_usage: 0.0,
            memory_usage: 0.0,
            start_time: timestamp_now(),
            node_name: "node-" + to_string(i % engine.cluster.node_count)
        }
        push(engine.cluster.pods, pod)
        i = i + 1
    }

    log_event(engine, "Normal", "DeploymentCreated",
              "Created deployment " + spec.name + " with " + to_string(spec.pod_spec.replicas) + " replicas")

    return engine
}

fn rolling_update(engine: DeploymentEngine, deploy_name: string,
                   new_image: string) -> DeploymentEngine {
    let deploy_idx = find_deployment(engine, deploy_name)
    if deploy_idx < 0 {
        log_event(engine, "Warning", "DeploymentNotFound",
                  "Deployment " + deploy_name + " not found")
        return engine
    }

    let deploy = engine.cluster.deployments[deploy_idx]
    deploy.status = "progressing"
    deploy.deploy_start_time = timestamp_now()
    deploy.current_revision = deploy.current_revision + 1

    // Save current state for rollback
    push(engine.rollback_stack, deploy)

    // Simulate rolling update: replace pods one by one
    let replicas = deploy.spec.pod_spec.replicas
    let max_surge = deploy.spec.max_surge
    let max_unavailable = deploy.spec.max_unavailable

    // Phase 1: Create surge pods with new image
    let surge_count = min_i32(max_surge, replicas)
    let i = 0
    while i < surge_count {
        let pod = PodState {
            name: deploy_name + "-new-" + to_string(i),
            deployment: deploy_name,
            status: "running",
            ready: true,
            restart_count: 0,
            cpu_usage: 0.05,
            memory_usage: 0.1,
            start_time: timestamp_now(),
            node_name: "node-" + to_string(i % engine.cluster.node_count)
        }
        push(engine.cluster.pods, pod)
        i = i + 1
    }

    // Phase 2: Replace old pods
    deploy.updated_replicas = replicas
    deploy.ready_replicas = replicas
    deploy.available_replicas = replicas
    deploy.status = "available"
    deploy.deploy_end_time = timestamp_now()
    deploy.deploy_duration_ms = (deploy.deploy_end_time - deploy.deploy_start_time) * 1000.0

    engine.cluster.deployments[deploy_idx] = deploy

    // Update average deploy time
    let n = engine.total_deployments
    engine.avg_deploy_time_ms = ((engine.avg_deploy_time_ms * (n - 1)) + deploy.deploy_duration_ms) / n

    log_event(engine, "Normal", "RollingUpdate",
              "Updated deployment " + deploy_name + " to revision " + to_string(deploy.current_revision))

    return engine
}

fn rollback_deployment(engine: DeploymentEngine, deploy_name: string) -> DeploymentEngine {
    if length(engine.rollback_stack) == 0 {
        log_event(engine, "Warning", "NoRollback", "No rollback available for " + deploy_name)
        return engine
    }

    // Pop from rollback stack
    let prev_state = engine.rollback_stack[length(engine.rollback_stack) - 1]
    let new_stack = []
    let i = 0
    while i < length(engine.rollback_stack) - 1 {
        push(new_stack, engine.rollback_stack[i])
        i = i + 1
    }
    engine.rollback_stack = new_stack

    let deploy_idx = find_deployment(engine, deploy_name)
    if deploy_idx >= 0 {
        engine.cluster.deployments[deploy_idx] = prev_state
        engine.cluster.deployments[deploy_idx].status = "available"
    }

    log_event(engine, "Normal", "Rollback",
              "Rolled back " + deploy_name + " to revision " + to_string(prev_state.current_revision))

    return engine
}

fn scale_deployment(engine: DeploymentEngine, deploy_name: string,
                     replicas: i32) -> DeploymentEngine {
    let deploy_idx = find_deployment(engine, deploy_name)
    if deploy_idx < 0 { return engine }

    let deploy = engine.cluster.deployments[deploy_idx]
    let old_replicas = deploy.spec.pod_spec.replicas
    deploy.spec.pod_spec.replicas = replicas

    if replicas > old_replicas {
        // Scale up: add pods
        let i = old_replicas
        while i < replicas {
            let pod = PodState {
                name: deploy_name + "-pod-" + to_string(i),
                deployment: deploy_name,
                status: "running",
                ready: true,
                restart_count: 0,
                cpu_usage: 0.05,
                memory_usage: 0.1,
                start_time: timestamp_now(),
                node_name: "node-" + to_string(i % engine.cluster.node_count)
            }
            push(engine.cluster.pods, pod)
            i = i + 1
        }
    }

    deploy.ready_replicas = replicas
    deploy.available_replicas = replicas
    engine.cluster.deployments[deploy_idx] = deploy

    log_event(engine, "Normal", "Scaled",
              "Scaled " + deploy_name + " from " + to_string(old_replicas) + " to " + to_string(replicas))

    return engine
}

// --- Service Operations ----------------------------------------------------

fn create_service(engine: DeploymentEngine, spec: ServiceSpec) -> DeploymentEngine {
    push(engine.cluster.services, spec)
    log_event(engine, "Normal", "ServiceCreated",
              "Created service " + spec.name + " type " + spec.service_type)
    return engine
}

// --- HPA Operations --------------------------------------------------------

fn create_hpa(engine: DeploymentEngine, spec: HPASpec) -> DeploymentEngine {
    push(engine.cluster.hpas, spec)
    log_event(engine, "Normal", "HPACreated",
              "Created HPA " + spec.name + " [" + to_string(spec.min_replicas) + "-" + to_string(spec.max_replicas) + "]")
    return engine
}

fn evaluate_hpa(engine: DeploymentEngine, hpa_name: string,
                 current_cpu: f32) -> i32 {
    // Find HPA
    let i = 0
    while i < length(engine.cluster.hpas) {
        let hpa = engine.cluster.hpas[i]
        if hpa.name == hpa_name {
            let target = hpa.cpu_target_percent * 1.0 / 100.0
            let ratio = current_cpu / target
            let desired = floor(ratio * hpa.min_replicas)
            desired = max_i32(hpa.min_replicas, min_i32(hpa.max_replicas, desired))
            return desired
        }
        i = i + 1
    }
    return 1
}

// --- Health Checking -------------------------------------------------------

fn check_deployment_health(engine: DeploymentEngine, deploy_name: string) -> bool {
    let deploy_idx = find_deployment(engine, deploy_name)
    if deploy_idx < 0 { return false }

    let deploy = engine.cluster.deployments[deploy_idx]

    // Check all pods are ready
    let ready_count = 0
    let total_count = 0
    let i = 0
    while i < length(engine.cluster.pods) {
        if engine.cluster.pods[i].deployment == deploy_name {
            total_count = total_count + 1
            if engine.cluster.pods[i].ready {
                ready_count = ready_count + 1
            }
        }
        i = i + 1
    }

    let healthy = ready_count == deploy.spec.pod_spec.replicas

    if healthy {
        engine.health_checker.consecutive_failures = 0
        engine.health_checker.is_healthy = true
    } else {
        engine.health_checker.consecutive_failures = engine.health_checker.consecutive_failures + 1
        if engine.health_checker.consecutive_failures >= engine.health_checker.max_failures {
            engine.health_checker.is_healthy = false
            if engine.config.auto_rollback {
                engine = rollback_deployment(engine, deploy_name)
            }
        }
    }

    engine.health_checker.last_check_time = timestamp_now()
    return healthy
}

// --- Utility ---------------------------------------------------------------

fn find_deployment(engine: DeploymentEngine, name: string) -> i32 {
    let i = 0
    while i < length(engine.cluster.deployments) {
        if engine.cluster.deployments[i].spec.name == name {
            return i
        }
        i = i + 1
    }
    return -1
}

fn log_event(engine: DeploymentEngine, event_type: string, reason: string,
              message: string) -> DeploymentEngine {
    let event = K8sEvent {
        event_type: event_type,
        reason: reason,
        message: message,
        source: "deployment-engine",
        timestamp: timestamp_now(),
        count: 1
    }
    push(engine.cluster.events, event)
    return engine
}

fn get_cluster_status(engine: DeploymentEngine) -> string {
    let total_deploys = length(engine.cluster.deployments)
    let healthy_deploys = 0
    let i = 0
    while i < total_deploys {
        if engine.cluster.deployments[i].status == "available" {
            healthy_deploys = healthy_deploys + 1
        }
        i = i + 1
    }
    return to_string(healthy_deploys) + "/" + to_string(total_deploys) + " deployments healthy"
}

fn min_i32(a: i32, b: i32) -> i32 {
    if a < b { return a }
    return b
}

fn max_i32(a: i32, b: i32) -> i32 {
    if a > b { return a }
    return b
}

fn floor(x: f32) -> i32 {
    return x
}

fn timestamp_now() -> i32 {
    return 1709683200
}

// =============================================================================
// Backend Phase 4: Multi-Region Failover Engine
// =============================================================================
// Automatic failover across multiple regions with health monitoring,
// leader election, traffic routing, and data consistency guarantees.
//
// Unforgiving Rule R6: Failover < 5s (region switch)
// =============================================================================

// --- Failover Types ---------------------------------------------------------

struct Region {
    region_id: string,          // e.g., "us-east-1", "eu-west-1"
    endpoint: string,
    status: string,             // "active", "standby", "degraded", "down"
    priority: i32,              // lower = higher priority
    health_score: f32,          // 0.0-1.0
    latency_ms: f32,
    error_rate: f32,
    last_health_check: i32,
    active_connections: i32,
    capacity: i32,
    data_lag_ms: f32            // replication lag
}

struct FailoverConfig {
    health_check_interval_ms: i32,
    failover_threshold: f32,    // health score below this triggers failover
    recovery_threshold: f32,    // health score above this for recovery
    max_failover_time_ms: i32,  // R6: must be < 5000
    min_healthy_regions: i32,
    quorum_size: i32,           // for leader election
    drain_timeout_ms: i32,      // time to drain connections before failover
    cooldown_ms: i32            // min time between failovers
}

struct FailoverEngine {
    regions: array,             // array of Region
    config: FailoverConfig,
    active_region: string,      // current primary region
    failover_history: array,    // array of FailoverEvent
    leader_election: LeaderElection,
    traffic_router: TrafficRouter,
    is_in_failover: bool,
    last_failover_time: i32,
    total_failovers: i32,
    avg_failover_time_ms: f32
}

struct FailoverEvent {
    from_region: string,
    to_region: string,
    reason: string,
    start_time: i32,
    end_time: i32,
    duration_ms: f32,
    success: bool,
    connections_migrated: i32
}

struct LeaderElection {
    current_leader: string,
    term: i32,
    votes: array,
    election_timeout_ms: i32,
    last_heartbeat: i32,
    state: string               // "leader", "follower", "candidate"
}

struct TrafficRouter {
    routing_table: array,       // array of RouteEntry
    strategy: string,           // "active_passive", "active_active", "weighted"
    weights: array,             // per-region traffic weight
    sticky_sessions: bool
}

struct RouteEntry {
    region_id: string,
    weight: f32,
    is_primary: bool,
    is_healthy: bool
}

// --- Engine Creation -------------------------------------------------------

fn create_failover_engine(regions: array) -> FailoverEngine {
    let config = FailoverConfig {
        health_check_interval_ms: 1000,
        failover_threshold: 0.3,
        recovery_threshold: 0.8,
        max_failover_time_ms: 5000,
        min_healthy_regions: 1,
        quorum_size: 2,
        drain_timeout_ms: 2000,
        cooldown_ms: 30000
    }

    let leader = LeaderElection {
        current_leader: "",
        term: 0,
        votes: [],
        election_timeout_ms: 3000,
        last_heartbeat: timestamp_now(),
        state: "follower"
    }

    let routes = []
    let primary = ""
    let i = 0
    while i < length(regions) {
        let r = regions[i]
        push(routes, RouteEntry {
            region_id: r.region_id,
            weight: 0.0,
            is_primary: i == 0,
            is_healthy: true
        })
        if i == 0 {
            primary = r.region_id
            routes[0].weight = 1.0
        }
        i = i + 1
    }

    let router = TrafficRouter {
        routing_table: routes,
        strategy: "active_passive",
        weights: [],
        sticky_sessions: true
    }

    return FailoverEngine {
        regions: regions,
        config: config,
        active_region: primary,
        failover_history: [],
        leader_election: leader,
        traffic_router: router,
        is_in_failover: false,
        last_failover_time: 0,
        total_failovers: 0,
        avg_failover_time_ms: 0.0
    }
}

// --- Health Monitoring -----------------------------------------------------

fn check_region_health(engine: FailoverEngine, region_id: string) -> FailoverEngine {
    let idx = find_region(engine, region_id)
    if idx < 0 { return engine }

    let region = engine.regions[idx]

    // Composite health score: latency + error_rate + data_lag
    let latency_score = 1.0
    if region.latency_ms > 100.0 { latency_score = 100.0 / region.latency_ms }
    if latency_score > 1.0 { latency_score = 1.0 }

    let error_score = 1.0 - region.error_rate
    if error_score < 0.0 { error_score = 0.0 }

    let lag_score = 1.0
    if region.data_lag_ms > 1000.0 { lag_score = 1000.0 / region.data_lag_ms }
    if lag_score > 1.0 { lag_score = 1.0 }

    // Weighted average
    region.health_score = 0.4 * latency_score + 0.4 * error_score + 0.2 * lag_score
    region.last_health_check = timestamp_now()

    // Update status based on health
    if region.health_score >= engine.config.recovery_threshold {
        region.status = "active"
    } else if region.health_score >= engine.config.failover_threshold {
        region.status = "degraded"
    } else {
        region.status = "down"
    }

    engine.regions[idx] = region

    // Check if failover is needed
    if region.region_id == engine.active_region && region.status == "down" {
        engine = trigger_failover(engine, region_id, "health_check_failed")
    }

    return engine
}

fn check_all_regions(engine: FailoverEngine) -> FailoverEngine {
    let i = 0
    while i < length(engine.regions) {
        engine = check_region_health(engine, engine.regions[i].region_id)
        i = i + 1
    }
    return engine
}

// --- Failover Execution ----------------------------------------------------

fn trigger_failover(engine: FailoverEngine, failed_region: string,
                     reason: string) -> FailoverEngine {
    // Check cooldown
    let now = timestamp_now()
    if engine.is_in_failover {
        return engine
    }
    if now - engine.last_failover_time < engine.config.cooldown_ms / 1000 {
        return engine
    }

    engine.is_in_failover = true
    let start_time = now

    // Find best target region
    let target = select_failover_target(engine, failed_region)
    if target == "" {
        engine.is_in_failover = false
        return engine
    }

    // Phase 1: Drain connections from failed region (simulated)
    // In production: graceful connection drain

    // Phase 2: Switch traffic to target
    engine = switch_traffic(engine, target)

    // Phase 3: Update routing table
    let i = 0
    while i < length(engine.traffic_router.routing_table) {
        if engine.traffic_router.routing_table[i].region_id == failed_region {
            engine.traffic_router.routing_table[i].is_primary = false
            engine.traffic_router.routing_table[i].is_healthy = false
            engine.traffic_router.routing_table[i].weight = 0.0
        }
        if engine.traffic_router.routing_table[i].region_id == target {
            engine.traffic_router.routing_table[i].is_primary = true
            engine.traffic_router.routing_table[i].weight = 1.0
        }
        i = i + 1
    }

    let end_time = timestamp_now()
    let duration = (end_time - start_time) * 1000.0

    // Record event
    let event = FailoverEvent {
        from_region: failed_region,
        to_region: target,
        reason: reason,
        start_time: start_time,
        end_time: end_time,
        duration_ms: duration,
        success: true,
        connections_migrated: 0
    }
    push(engine.failover_history, event)

    engine.active_region = target
    engine.is_in_failover = false
    engine.last_failover_time = end_time
    engine.total_failovers = engine.total_failovers + 1

    // Update average
    let n = engine.total_failovers
    engine.avg_failover_time_ms = ((engine.avg_failover_time_ms * (n - 1)) + duration) / n

    return engine
}

fn select_failover_target(engine: FailoverEngine, exclude: string) -> string {
    let best_region = ""
    let best_score = -1.0
    let best_priority = 999999

    let i = 0
    while i < length(engine.regions) {
        let r = engine.regions[i]
        if r.region_id != exclude && r.status != "down" {
            // Prefer: higher health, lower priority number
            if r.health_score > engine.config.failover_threshold {
                if r.priority < best_priority ||
                   (r.priority == best_priority && r.health_score > best_score) {
                    best_region = r.region_id
                    best_score = r.health_score
                    best_priority = r.priority
                }
            }
        }
        i = i + 1
    }
    return best_region
}

fn switch_traffic(engine: FailoverEngine, target: string) -> FailoverEngine {
    engine.active_region = target
    return engine
}

// --- Leader Election (Simplified Raft) -------------------------------------

fn start_election(engine: FailoverEngine, candidate: string) -> FailoverEngine {
    engine.leader_election.term = engine.leader_election.term + 1
    engine.leader_election.state = "candidate"
    engine.leader_election.votes = [candidate]

    // Simulate vote collection
    let i = 0
    while i < length(engine.regions) {
        let r = engine.regions[i]
        if r.region_id != candidate && r.status != "down" {
            // Vote for candidate if no leader in current term
            push(engine.leader_election.votes, r.region_id)
        }
        i = i + 1
    }

    // Check if won majority
    if length(engine.leader_election.votes) >= engine.config.quorum_size {
        engine.leader_election.current_leader = candidate
        engine.leader_election.state = "leader"
    } else {
        engine.leader_election.state = "follower"
    }

    return engine
}

// --- Utility ---------------------------------------------------------------

fn find_region(engine: FailoverEngine, region_id: string) -> i32 {
    let i = 0
    while i < length(engine.regions) {
        if engine.regions[i].region_id == region_id {
            return i
        }
        i = i + 1
    }
    return -1
}

fn get_healthy_region_count(engine: FailoverEngine) -> i32 {
    let count = 0
    let i = 0
    while i < length(engine.regions) {
        if engine.regions[i].status == "active" || engine.regions[i].status == "degraded" {
            count = count + 1
        }
        i = i + 1
    }
    return count
}

fn timestamp_now() -> i32 {
    return 1709683200
}

// =============================================================================
// Backend Phase 4: Observability Stack (Tracing + Metrics + Logging)
// =============================================================================
// Full observability pipeline: distributed tracing, metrics collection,
// structured logging, alerting, and SLO monitoring.
//
// Unforgiving Rule R7: Trace sampling > 1%
// Unforgiving Rule R8: Log retention 30 days
// =============================================================================

// --- Tracing Types ----------------------------------------------------------

struct Span {
    trace_id: string,
    span_id: string,
    parent_span_id: string,
    operation_name: string,
    service_name: string,
    start_time: i32,
    end_time: i32,
    duration_ms: f32,
    status: string,             // "ok", "error", "timeout"
    tags: array,                // array of Tag
    logs: array,                // array of SpanLog
    baggage: array              // context propagation
}

struct Tag {
    key: string,
    value: string
}

struct SpanLog {
    timestamp: i32,
    message: string,
    level: string
}

struct Trace {
    trace_id: string,
    root_span: Span,
    spans: array,
    service_count: i32,
    total_duration_ms: f32,
    has_error: bool,
    sampled: bool
}

struct TracingConfig {
    sample_rate: f32,           // R7: must be > 0.01 (1%)
    max_spans_per_trace: i32,
    max_tag_length: i32,
    propagation_format: string, // "w3c", "b3", "jaeger"
    exporter: string,           // "jaeger", "zipkin", "otlp"
    buffer_size: i32
}

struct TracingEngine {
    config: TracingConfig,
    active_traces: array,
    completed_traces: array,
    sampler: Sampler,
    total_spans: i32,
    total_traces: i32,
    sampled_traces: i32,
    error_traces: i32
}

struct Sampler {
    strategy: string,           // "always", "never", "probability", "rate_limiting"
    probability: f32,
    rate_per_second: f32,
    current_count: i32,
    last_reset: i32
}

// --- Metrics Types ----------------------------------------------------------

struct MetricPoint {
    name: string,
    metric_type: string,        // "counter", "gauge", "histogram", "summary"
    value: f32,
    timestamp: i32,
    labels: array               // array of Tag
}

struct Histogram {
    name: string,
    buckets: array,             // bucket boundaries
    counts: array,              // per-bucket counts
    sum: f32,
    count: i32,
    labels: array
}

struct MetricsConfig {
    scrape_interval_s: i32,
    retention_days: i32,        // R8: must be >= 30
    max_series: i32,
    export_format: string       // "prometheus", "otlp", "statsd"
}

struct MetricsEngine {
    config: MetricsConfig,
    counters: array,            // array of MetricPoint (counter type)
    gauges: array,
    histograms: array,
    total_points: i32,
    oldest_point_time: i32,
    newest_point_time: i32
}

// --- Logging Types ----------------------------------------------------------

struct LogEntry {
    timestamp: i32,
    level: string,              // "DEBUG", "INFO", "WARN", "ERROR", "FATAL"
    message: string,
    service: string,
    trace_id: string,
    span_id: string,
    fields: array,              // structured fields (array of Tag)
    caller: string              // source file:line
}

struct LoggingConfig {
    min_level: string,
    retention_days: i32,        // R8: 30 days
    max_size_mb: i32,
    rotation_strategy: string,  // "daily", "size", "both"
    format: string,             // "json", "text", "logfmt"
    output: string              // "stdout", "file", "both"
}

struct LoggingEngine {
    config: LoggingConfig,
    buffer: array,              // buffered log entries
    buffer_size: i32,
    total_entries: i32,
    entries_by_level: array,    // [debug, info, warn, error, fatal]
    oldest_entry_time: i32,
    newest_entry_time: i32
}

// --- SLO Monitoring ---------------------------------------------------------

struct SLO {
    name: string,
    target: f32,                // e.g., 0.999 for 99.9%
    window_days: i32,           // e.g., 30 days
    metric_name: string,
    threshold: f32,             // success threshold
    current_value: f32,
    error_budget_remaining: f32,
    is_burning: bool            // burning error budget too fast
}

struct AlertRule {
    name: string,
    condition: string,          // metric condition
    threshold: f32,
    duration_s: i32,            // must be true for this long
    severity: string,           // "critical", "warning", "info"
    notification_channel: string,
    last_fired: i32,
    is_firing: bool,
    silenced: bool
}

// --- Observability Stack ---------------------------------------------------

struct ObservabilityStack {
    tracing: TracingEngine,
    metrics: MetricsEngine,
    logging: LoggingEngine,
    slos: array,                // array of SLO
    alerts: array,              // array of AlertRule
    correlation_enabled: bool    // correlate traces <-> logs <-> metrics
}

// --- Stack Creation --------------------------------------------------------

fn create_observability_stack() -> ObservabilityStack {
    let tracing_config = TracingConfig {
        sample_rate: 0.05,      // 5% > R7 threshold of 1%
        max_spans_per_trace: 100,
        max_tag_length: 256,
        propagation_format: "w3c",
        exporter: "otlp",
        buffer_size: 1000
    }

    let sampler = Sampler {
        strategy: "probability",
        probability: 0.05,
        rate_per_second: 100.0,
        current_count: 0,
        last_reset: timestamp_now()
    }

    let tracing = TracingEngine {
        config: tracing_config,
        active_traces: [],
        completed_traces: [],
        sampler: sampler,
        total_spans: 0,
        total_traces: 0,
        sampled_traces: 0,
        error_traces: 0
    }

    let metrics_config = MetricsConfig {
        scrape_interval_s: 15,
        retention_days: 30,     // R8: exactly 30 days
        max_series: 10000,
        export_format: "prometheus"
    }

    let metrics = MetricsEngine {
        config: metrics_config,
        counters: [],
        gauges: [],
        histograms: [],
        total_points: 0,
        oldest_point_time: timestamp_now(),
        newest_point_time: timestamp_now()
    }

    let logging_config = LoggingConfig {
        min_level: "INFO",
        retention_days: 30,     // R8: 30 days
        max_size_mb: 1024,
        rotation_strategy: "daily",
        format: "json",
        output: "both"
    }

    let logging = LoggingEngine {
        config: logging_config,
        buffer: [],
        buffer_size: 0,
        total_entries: 0,
        entries_by_level: [0, 0, 0, 0, 0],
        oldest_entry_time: timestamp_now(),
        newest_entry_time: timestamp_now()
    }

    return ObservabilityStack {
        tracing: tracing,
        metrics: metrics,
        logging: logging,
        slos: [],
        alerts: [],
        correlation_enabled: true
    }
}

// --- Tracing Operations ----------------------------------------------------

fn start_trace(stack: ObservabilityStack, operation: string,
                service: string) -> Trace {
    let trace_id = generate_trace_id(stack.tracing.total_traces)
    let span_id = generate_span_id(0)

    let should_sample = decide_sample(stack.tracing.sampler)

    let root_span = Span {
        trace_id: trace_id,
        span_id: span_id,
        parent_span_id: "",
        operation_name: operation,
        service_name: service,
        start_time: timestamp_now(),
        end_time: 0,
        duration_ms: 0.0,
        status: "ok",
        tags: [],
        logs: [],
        baggage: []
    }

    let trace = Trace {
        trace_id: trace_id,
        root_span: root_span,
        spans: [root_span],
        service_count: 1,
        total_duration_ms: 0.0,
        has_error: false,
        sampled: should_sample
    }

    stack.tracing.total_traces = stack.tracing.total_traces + 1
    stack.tracing.total_spans = stack.tracing.total_spans + 1
    if should_sample {
        stack.tracing.sampled_traces = stack.tracing.sampled_traces + 1
        push(stack.tracing.active_traces, trace)
    }

    return trace
}

fn add_span(trace: Trace, operation: string, service: string,
             parent_id: string) -> Trace {
    let span_id = generate_span_id(length(trace.spans))

    let span = Span {
        trace_id: trace.trace_id,
        span_id: span_id,
        parent_span_id: parent_id,
        operation_name: operation,
        service_name: service,
        start_time: timestamp_now(),
        end_time: 0,
        duration_ms: 0.0,
        status: "ok",
        tags: [],
        logs: [],
        baggage: []
    }

    push(trace.spans, span)
    return trace
}

fn end_trace(stack: ObservabilityStack, trace: Trace) -> ObservabilityStack {
    trace.root_span.end_time = timestamp_now()
    trace.root_span.duration_ms = (trace.root_span.end_time - trace.root_span.start_time) * 1000.0
    trace.total_duration_ms = trace.root_span.duration_ms

    if trace.has_error {
        stack.tracing.error_traces = stack.tracing.error_traces + 1
    }

    // Move from active to completed
    push(stack.tracing.completed_traces, trace)

    return stack
}

fn decide_sample(sampler: Sampler) -> bool {
    if sampler.strategy == "always" { return true }
    if sampler.strategy == "never" { return false }

    // Probability sampling
    sampler.current_count = sampler.current_count + 1
    let hash = (sampler.current_count * 2654435761) % 10000
    let threshold = sampler.probability * 10000.0
    return hash < threshold
}

fn get_sample_rate(stack: ObservabilityStack) -> f32 {
    if stack.tracing.total_traces == 0 { return 0.0 }
    return stack.tracing.sampled_traces * 1.0 / stack.tracing.total_traces
}

fn generate_trace_id(seq: i32) -> string {
    return "trace-" + to_string(seq) + "-" + to_string(timestamp_now())
}

fn generate_span_id(seq: i32) -> string {
    return "span-" + to_string(seq)
}

// --- Metrics Operations ----------------------------------------------------

fn record_counter(stack: ObservabilityStack, name: string, value: f32,
                   labels: array) -> ObservabilityStack {
    let point = MetricPoint {
        name: name,
        metric_type: "counter",
        value: value,
        timestamp: timestamp_now(),
        labels: labels
    }
    push(stack.metrics.counters, point)
    stack.metrics.total_points = stack.metrics.total_points + 1
    stack.metrics.newest_point_time = timestamp_now()
    return stack
}

fn record_gauge(stack: ObservabilityStack, name: string, value: f32,
                 labels: array) -> ObservabilityStack {
    let point = MetricPoint {
        name: name,
        metric_type: "gauge",
        value: value,
        timestamp: timestamp_now(),
        labels: labels
    }
    push(stack.metrics.gauges, point)
    stack.metrics.total_points = stack.metrics.total_points + 1
    return stack
}

fn record_histogram(stack: ObservabilityStack, name: string,
                     value: f32) -> ObservabilityStack {
    // Find or create histogram
    let found = false
    let i = 0
    while i < length(stack.metrics.histograms) {
        if stack.metrics.histograms[i].name == name {
            let h = stack.metrics.histograms[i]
            h.sum = h.sum + value
            h.count = h.count + 1
            // Update bucket counts
            let j = 0
            while j < length(h.buckets) {
                if value <= h.buckets[j] {
                    h.counts[j] = h.counts[j] + 1
                }
                j = j + 1
            }
            stack.metrics.histograms[i] = h
            found = true
            break
        }
        i = i + 1
    }

    if !found {
        let h = Histogram {
            name: name,
            buckets: [1.0, 5.0, 10.0, 25.0, 50.0, 100.0, 250.0, 500.0, 1000.0],
            counts: [0, 0, 0, 0, 0, 0, 0, 0, 0],
            sum: value,
            count: 1,
            labels: []
        }
        push(stack.metrics.histograms, h)
    }

    stack.metrics.total_points = stack.metrics.total_points + 1
    return stack
}

fn get_retention_days(stack: ObservabilityStack) -> i32 {
    return stack.metrics.config.retention_days
}

// --- Logging Operations ----------------------------------------------------

fn log_entry(stack: ObservabilityStack, level: string, message: string,
              service: string, trace_id: string) -> ObservabilityStack {
    let entry = LogEntry {
        timestamp: timestamp_now(),
        level: level,
        message: message,
        service: service,
        trace_id: trace_id,
        span_id: "",
        fields: [],
        caller: ""
    }

    push(stack.logging.buffer, entry)
    stack.logging.buffer_size = stack.logging.buffer_size + 1
    stack.logging.total_entries = stack.logging.total_entries + 1
    stack.logging.newest_entry_time = timestamp_now()

    // Update level counts
    if level == "DEBUG" { stack.logging.entries_by_level[0] = stack.logging.entries_by_level[0] + 1 }
    else if level == "INFO" { stack.logging.entries_by_level[1] = stack.logging.entries_by_level[1] + 1 }
    else if level == "WARN" { stack.logging.entries_by_level[2] = stack.logging.entries_by_level[2] + 1 }
    else if level == "ERROR" { stack.logging.entries_by_level[3] = stack.logging.entries_by_level[3] + 1 }
    else if level == "FATAL" { stack.logging.entries_by_level[4] = stack.logging.entries_by_level[4] + 1 }

    return stack
}

fn get_log_retention_days(stack: ObservabilityStack) -> i32 {
    return stack.logging.config.retention_days
}

// --- SLO Operations --------------------------------------------------------

fn add_slo(stack: ObservabilityStack, name: string, target: f32,
            window: i32) -> ObservabilityStack {
    let slo = SLO {
        name: name,
        target: target,
        window_days: window,
        metric_name: "",
        threshold: 0.0,
        current_value: 1.0,
        error_budget_remaining: 1.0 - target,
        is_burning: false
    }
    push(stack.slos, slo)
    return stack
}

fn update_slo(stack: ObservabilityStack, slo_name: string,
               success_count: i32, total_count: i32) -> ObservabilityStack {
    let i = 0
    while i < length(stack.slos) {
        if stack.slos[i].name == slo_name {
            let slo = stack.slos[i]
            if total_count > 0 {
                slo.current_value = success_count * 1.0 / total_count
            }
            slo.error_budget_remaining = slo.target - (1.0 - slo.current_value)
            slo.is_burning = slo.error_budget_remaining < 0.0
            stack.slos[i] = slo
            break
        }
        i = i + 1
    }
    return stack
}

// --- Alert Operations ------------------------------------------------------

fn add_alert(stack: ObservabilityStack, name: string, threshold: f32,
              severity: string) -> ObservabilityStack {
    let alert = AlertRule {
        name: name,
        condition: "",
        threshold: threshold,
        duration_s: 60,
        severity: severity,
        notification_channel: "default",
        last_fired: 0,
        is_firing: false,
        silenced: false
    }
    push(stack.alerts, alert)
    return stack
}

fn check_alerts(stack: ObservabilityStack) -> array {
    let firing = []
    let i = 0
    while i < length(stack.alerts) {
        if stack.alerts[i].is_firing && !stack.alerts[i].silenced {
            push(firing, stack.alerts[i])
        }
        i = i + 1
    }
    return firing
}

